    rep.forEach(function (r) { s = s.replace(r[0], r[1]); });
    if (s === 'HD' && pa && /(^|[\s-])av(\s|$)/.test(typeof pa.className === 'string' ? pa.className : '')) s = TC_TAT;
    if (s !== o) t.nodeValue = s;
